           active[i] = false;
         } else if (bin < threshold_bin) {
           active[i] = false;
-        } else if (round == 3) {
+        } else if (round == 7 || equal_count == topk_remain) {
           write_pos[i] = topk - topk_remain + atomicAdd(&smem->counter_final, 1);
         }
